sub usage {
    my $self = shift;
    my $message = shift;

    # Send the specified message to STDERR
    warn "$message\n";

    # Get the command name
    my $command = $self->command;

    # Define the possible documentation sections
    my @sections = qw(Name Synopsis Options);

    # Try to find the documentation for the command
    foreach my $section (@sections) {
        my $doc = $self->_pod2usage(
            '-section' => $section,
            '-input'   => "sqitch-$command-usage",
        );

        # If the documentation was found, print it and exit
        if ($doc) {
            print $doc;
            exit 2;
        }
    }

    # If no documentation was found, print a generic error message
    warn "No documentation found for command '$command'\n";
    exit 2;
}

