    if (!$target || $target !~ m{^\w+://}) {
        hurl upgrade => __ 'No target specified';
    }

    # If the target is a file URI, hurl.
    if ($target =~ m{^file://}) {
        hurl upgrade => __x 'Cannot upgrade from file URI {uri}', uri => $target;
    }

    # If the target is a database URI, upgrade.
    if ($target =~ m{^dbi://}) {
        # Get the target database handle.
        my $dbh = $self->_get_dbh($target);

        # Get the current schema version.
        my $cur_ver = $self->_get_current_version($dbh);

        # Get the target version.
        my $target_ver = $self->_get_target_version($dbh);

        # If the current version is greater than the target version, hurl.
        if ($cur_ver > $target_ver) {
            hurl upgrade => __x 'Current version {cur_ver} is greater than target version {target_ver}',
                cur_ver => $cur_ver, target_ver => $target_ver;
        }

        # Get the scripts to upgrade.
        my @scripts = $self->_get_upgrade_scripts($dbh, $cur_ver, $target_ver);

        # If there are no scripts to upgrade, hurl.
        if (!@scripts) {
            hurl upgrade => __x 'No scripts to upgrade from version {cur_ver} to {target_ver}',
                cur_ver => $cur_ver, target_ver => $target_ver;
        }

        # Upgrade the scripts.
        $self->_upgrade_scripts($dbh, @scripts);
    }
}

