    my ($class, %p) = @_;
    my $sqitch = $p{sqitch} // hurl 'Missing sqitch parameter';
    my $config = $sqitch->config;
    my %targets;

    # Get all targets from the configuration
    for my $key ($config->keys('target')) {
        my $target = $class->new(%p, name => $key);
        $targets{$target->name} = $target;
    }

    # Get all engines from the configuration
    for my $key ($config->keys('engine')) {
        my $target = $class->new(%p, name => "db:$key:");
        $targets{$target->name} = $target;
    }

    # Get the core target
    my $target = $class->new(%p, name => 'core');
    $targets{$target->name} = $target;

    # Return the targets as a list
    return [values %targets];
}
